(async () => {
  console.log("all:", await Promise.all([p1(), p3()]));
  try { await Promise.all([p1(), p2(), p3()]); }
  catch (e) { console.log("all rejected with:", e); }

  const settled = await Promise.allSettled([p1(), p2(), p3()]);
