function fakeFetch(url, { signal } = {}) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve({ ok: true, json: async () => ({ url, joke: "Hello!" }) }), 50);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("The operation was aborted.", "AbortError"));
    });
  });
}

(async () => {
  const res = await fakeFetch("/api/joke");
  console.log("ok:", res.ok, await res.json());

  const controller = new AbortController();
  const pending = fakeFetch("/api/slow", { signal: controller.signal });
  controller.abort();
  try { await pending; } catch (e) { console.log("cancelled:", e.name); }
})();

