  static instances = 0;
  static #max = 3;
  static { Counter.label = 'counter'; }
  #n = 0;
  step = 1;
  constructor() {
    if (Counter.instances >= Counter.#max) throw new Error('limit');
    Counter.instances++;
  }
  inc() { this.#n += this.step; return this; }
  get value() { return this.#n; }
  set value(v) { if (v < 0) throw new RangeError('neg'); this.#n = v; }
  static isCounter(o) { return #n in o; }
}
