function a() { try { return "try"; } finally { console.log("finally runs after return is evaluated"); } }
function b() { try { return "try"; } finally { return "finally"; } }           // overrides
function c() { try { throw new Error("lost"); } finally { return "swallowed"; } } // error swallowed!
function d() {
  try { throw new Error("first"); }
  catch (e) { throw new Error("from catch"); }
  finally { console.log("cleanup always runs"); }
}
