  async call(...args) {
    if (this.failures >= this.failureThreshold && this.skipped < this.cooldownCalls) {
      this.skipped++;
      throw new Error("circuit open: skipping call");
    }
    try { const r = await this.fn(...args); this.failures = 0; this.skipped = 0; return r; }
    catch (e) { this.failures++; this.skipped = 0; throw e; }
  }
}
