class ApiResponseError extends Error {
  constructor(message, { status, snippet, cause } = {}) { super(message, { cause }); this.name = "ApiResponseError"; this.status = status; this.snippet = snippet; }
}
async function readJson(res) {
  const text = await res.text();
  if (!res.ok) throw new ApiResponseError("HTTP " + res.status, { status: res.status, snippet: text.slice(0, 60) });
  if (res.status === 204 || text.trim() === "") return null;
  const type = res.headers.get("content-type") || "";
  if (!/json/i.test(type)) throw new ApiResponseError("Expected JSON but got " + (type || "no content-type"), { status: res.status, snippet: text.slice(0, 60) });
  try { return JSON.parse(text.replace(/^﻿/, "")); }
  catch (e) { throw new ApiResponseError("Invalid JSON from server", { status: res.status, snippet: text.slice(0, 60), cause: e }); }
}
