// Simulate a Storage that throws like a full browser storage
class TinyStorage {
  constructor(limit) { this.limit = limit; this.map = new Map(); }
  setItem(k, v) {
    const used = [...this.map.values()].join("").length;
    if (used + String(v).length > this.limit) throw new DOMException("Setting the value of '" + k + "' exceeded the quota.", "QuotaExceededError");
    this.map.set(k, String(v));
  }
  getItem(k) { return this.map.has(k) ? this.map.get(k) : null; }
  removeItem(k) { this.map.delete(k); }
}
function createSafeStore(storage) {
  const memory = new Map();
  return {
    set(key, value) {
      const text = JSON.stringify({ v: 1, data: value });
      try { storage.setItem(key, text); return "stored"; }
      catch (e) {
        if (e.name === "QuotaExceededError") { memory.set(key, text); return "quota full -> kept in memory"; }
        throw e;
      }
    },
    get(key, fallback = null) {
      const text = storage.getItem(key) ?? memory.get(key);
      if (text == null) return fallback;
      try { const parsed = JSON.parse(text); return parsed.v === 1 ? parsed.data : fallback; }
      catch { return fallback; }
    },
  };
}
const store = createSafeStore(new TinyStorage(40));
console.log(store.set("theme", "dark"));
console.log(store.set("bigList", Array.from({ length: 30 }, (_, i) => i)));
console.log(store.get("theme"), store.get("bigList").length, store.get("missing", "default"));

