class FakeSocket {
  static attempt = 0;
  constructor() {
    FakeSocket.attempt++;
    setTimeout(() => {
      if (FakeSocket.attempt < 3) { this.onerror?.({}); this.onclose?.({ code: 1006, reason: "", wasClean: false }); }
      else { this.readyState = 1; this.onopen?.(); setTimeout(() => this.onclose?.({ code: 1000, wasClean: true }), 5); }
    }, 1);
    this.readyState = 0;
  }
  send(data) { if (this.readyState !== 1) throw new DOMException("Still in CONNECTING state.", "InvalidStateError"); }
}
function connect(attempt = 0) {
  const ws = new FakeSocket();
  const queue = [];
  ws.onopen = () => { console.log("open after", attempt, "retries"); queue.forEach((m) => ws.send(m)); };
  ws.onerror = () => console.log("error event (no details)");
  ws.onclose = (e) => {
    console.log("close code", e.code, e.code === 1006 ? "(abnormal)" : "(normal)");
    if (e.code !== 1000) {
      const delay = Math.min(30000, 5 * 2 ** attempt);
      console.log("reconnect in", delay, "ms");
      setTimeout(() => connect(attempt + 1), delay);
    }
  };
  try { ws.send("too early"); } catch (err) { console.log("send before open:", err.name); queue.push("hello"); }
}
connect();

function createSocket(url, { onMessage }) {
  let ws, attempt = 0, closedByUser = false, heartbeat;
  const queue = [];
  function open() {
    ws = new WebSocket(url);
    ws.onopen = () => {
      attempt = 0;
      queue.splice(0).forEach((m) => ws.send(m));
      heartbeat = setInterval(() => ws.readyState === WebSocket.OPEN && ws.send('{"type":"ping"}'), 25000);
    };
    ws.onmessage = (e) => onMessage(JSON.parse(e.data));
    ws.onclose = (e) => {
      clearInterval(heartbeat);
      if (closedByUser || e.code === 1000 || e.code === 4001) return;       // 4001: custom "unauthorized"
      const delay = Math.min(30000, 500 * 2 ** attempt++) + Math.random() * 250;
      setTimeout(open, delay);
    };
  }
  open();
  return {
    send(msg) { const text = JSON.stringify(msg); ws.readyState === WebSocket.OPEN ? ws.send(text) : queue.push(text); },
    close() { closedByUser = true; ws.close(1000); },
  };
}

